'use strict';
const $=id=>document.getElementById(id);
const fmt=new Intl.NumberFormat('en-GB',{maximumFractionDigits:0});
const dec=new Intl.NumberFormat('en-GB',{maximumFractionDigits:1});
const n=v=>fmt.format(v), pct=(a,b)=>b?dec.format(100*a/b)+'%':'—';
const esc=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
let data, labels, cols, selected=[], summary=[], activeMetric='fatal';
const metrics={fatal:'Fatal casualties',adjksi:'Adjusted KSI estimate',rawksi:'Recorded KSI',total:'All casualties'};
function switchTab(id){
 if(!['explore','findings','history','methods'].includes(id))id='explore';
 document.querySelectorAll('.tab-panel').forEach(e=>e.hidden=e.id!==id);
 document.querySelectorAll('nav [data-tab]').forEach(e=>{e.classList.toggle('active',e.dataset.tab===id);if(e.dataset.tab===id)e.setAttribute('aria-current','page');else e.removeAttribute('aria-current');});
}
document.querySelectorAll('[data-tab]').forEach(e=>e.addEventListener('click',()=>switchTab(e.dataset.tab)));
window.addEventListener('hashchange',()=>switchTab(location.hash.slice(1)));switchTab(location.hash.slice(1));
function options(id,arr,all=true){$(id).innerHTML=(all?'<option value="all">All</option>':'')+arr.map(([v,l])=>`<option value="${esc(v)}">${esc(l)}</option>`).join('');}
function value(r,metric=activeMetric){const severity=r[cols.severity],count=r[cols.n];return metric==='total'?count:metric==='fatal'?(severity===1?count:0):metric==='rawksi'?(severity<=2?count:0):(severity===1?count:0)+r[cols.adjusted_serious];}
function total(rows,metric){return rows.reduce((s,r)=>s+value(r,metric),0);}
function group(rows,key,metric=activeMetric){const out=new Map();for(const r of rows){let k=r[cols[key]];out.set(k,(out.get(k)||0)+value(r,metric));}return out;}
function table(headers,rows){return '<table><thead><tr>'+headers.map(x=>`<th scope="col">${esc(x)}</th>`).join('')+'</tr></thead><tbody>'+rows.map(r=>'<tr>'+r.map((x,i)=>i?`<td>${esc(x)}</td>`:`<th scope="row">${esc(x)}</th>`).join('')+'</tr>').join('')+'</tbody></table>';}
function bars(id,key,labelMap,order=null,top=null){
 const g=group(selected,key),den=total(selected,activeMetric);
 let entries=order?order.map(k=>[k,g.get(k)||0]):[...g].sort((a,b)=>b[1]-a[1]);
 if(top)entries=entries.slice(0,top);
 const max=Math.max(1,...entries.map(x=>x[1]));
 $(id).innerHTML='<div class="bars">'+entries.map(([k,v])=>`<div class="bar-row"><span class="bar-name">${esc(labelMap[k]??'Unknown')}</span><div class="bar-track" aria-hidden="true"><div class="bar-fill" style="width:${v/max*100}%"></div></div><span class="bar-value">${n(v)}<small>${pct(v,den)}</small></span></div>`).join('')+'</div>';
}
function chart(id,series,title,line=false){
 const W=1060,H=285,left=58,right=25,top=30,bottom=42,w=W-left-right,h=H-top-bottom,max=Math.max(1,...series.map(x=>x.value))*1.12;
 const xx=i=>left+(line?(series.length===1?w/2:i*w/(series.length-1)):(i+.5)*w/series.length),yy=v=>top+h-v/max*h;
 let s=`<svg viewBox="0 0 ${W} ${H}" role="img" aria-label="${esc(title)}"><title>${esc(title)}</title>`;
 for(let i=0;i<=4;i++){const v=max*i/4,y=yy(v);s+=`<line class="grid" x1="${left}" x2="${W-right}" y1="${y}" y2="${y}"/><text x="${left-12}" y="${y+4}" text-anchor="end">${n(v)}</text>`;}
 if(line){s+=`<polyline points="${series.map((x,i)=>xx(i)+','+yy(x.value)).join(' ')}" fill="none" stroke="#04315b" stroke-width="3"/>`;}
 series.forEach((d,i)=>{let x=xx(i),y=yy(d.value);if(line)s+=`<circle cx="${x}" cy="${y}" r="3" fill="#04315b"><title>${d.year}: ${n(d.value)}</title></circle>`;else{let bw=Math.min(60,w/series.length*.58);s+=`<rect x="${x-bw/2}" y="${y}" width="${bw}" height="${top+h-y}" rx="3" fill="${i===series.length-1?'#ffbb00':'#04315b'}"><title>${d.year}: ${n(d.value)}</title></rect><text class="data-label" x="${x}" y="${y-10}" text-anchor="middle">${n(d.value)}</text>`;}if(series.length<=12||i===0||i===series.length-1||d.year%5===0)s+=`<text x="${x}" y="${H-15}" text-anchor="middle">${d.year}</text>`;});
 $(id).innerHTML=s+'</svg>';
}
function render(){
 if(!data)return;
 let from=+$('from').value,to=+$('to').value;
 if(from>to){to=from;$('to').value=String(to);}
 const filters=['age','bike','area','role'].map(k=>[cols[k],$(k).value]);
 selected=data.explorer.rows.filter(r=>r[cols.year]>=from&&r[cols.year]<=to&&filters.every(([i,v])=>v==='all'||r[i]===+v));
 activeMetric=$('metric').value;
 const all=total(selected,'total'),fatal=total(selected,'fatal'),adj=total(selected,'adjksi');
 $('empty').hidden=all>0;
 const tags=['age','bike','area','role'].filter(k=>$(k).value!=='all').map(k=>labels[k][+$(k).value]);
 $('scope').textContent=`${from}–${to} · ${tags.length?tags.join(' · '):'All motorcycle categories, ages and road settings · Riders and passengers'}`;
 $('kpis').innerHTML=[['All casualties',n(all),'People injured or killed'],['Fatal casualties',n(fatal),'Recorded deaths'],['Adjusted KSI',n(adj),'Estimated killed or seriously injured'],['Adjusted KSI share',pct(adj,all),'Of selected casualties']].map(([a,b,c])=>`<div class="kpi"><span>${a}</span><strong>${b}</strong><small>${c}</small></div>`).join('');
 $('metric-note').textContent=activeMetric==='adjksi'?'Adjusted estimates can differ from recorded serious-injury counts. Displayed estimates are rounded.':activeMetric==='rawksi'?'Recorded KSI is affected by changes in severity reporting. Prefer adjusted KSI when comparing years.':activeMetric==='fatal'?'Fatal counts are relatively small. Treat short-term changes in narrow subgroups cautiously.':'Includes fatal, serious and slight casualties. A person is counted once in each recorded casualty event.';
 summary=Array.from({length:to-from+1},(_,i)=>{let year=from+i,rows=selected.filter(r=>r[cols.year]===year);return {year,total:total(rows,'total'),fatal:total(rows,'fatal'),rawksi:total(rows,'rawksi'),adjksi:total(rows,'adjksi')};});
 $('trend-sub').textContent=`${metrics[activeMetric]}, ${from}–${to}. ${from<=2020&&to>=2020?'2020 includes pandemic travel disruption.':''}`;
 $('trend-unit').textContent='Annual count';
 chart('trend',summary.map(x=>({year:x.year,value:x[activeMetric]})),`${metrics[activeMetric]} by year. Exact figures are in the annual table.`);
 $('annual-table').innerHTML=table(['Year','All casualties','Fatal','Recorded KSI','Adjusted KSI'],summary.map(x=>[x.year,n(x.total),n(x.fatal),n(x.rawksi),dec.format(x.adjksi)]));
 bars('age-chart','age',labels.age,labels.age.map((_,i)=>i));
 bars('bike-chart','bike',labels.bike,labels.bike.map((_,i)=>i));
 bars('area-chart','area',labels.area,[0,1,2]);bars('junction-chart','junction',labels.junction,[0,1,2]);
 bars('skid-chart','skid',labels.skid,[0,1,2,3,4]);bars('speed-chart','speed',{'20':'20 mph','30':'30 mph','40':'40 mph','50':'50 mph','60':'60 mph','70':'70 mph','-1':'Unknown'},[20,30,40,50,60,70,-1]);
 bars('force-chart','force',labels.force,null,10);
 $('missing').innerHTML=[['Age', 'age',8],['Junction','junction',2],['Skid / overturn','skid',4],['Bend status','bend',2]].map(([name,k,v])=>`<div><strong>${pct(selected.filter(r=>r[cols[k]]===v).reduce((s,r)=>s+r[cols.n],0),all)}</strong><span>${name} unavailable / unknown</span></div>`).join('');
}
function finding(number,caption,tag,title,text){return `<article class="finding"><div class="number">${number}<small>${caption}</small></div><div><span class="tag">${tag}</span><h3>${title}</h3>${text}</div></article>`;}
function renderFindings(){
 const a=data.annual.find(x=>x.year===2024),b=data.annual.find(x=>x.year===2025),c=data.claims;
 const ratio=b.fatal/a.fatal,delta=100*(ratio-1),se=Math.sqrt(1/a.fatal+1/b.fatal),lo=Math.exp(Math.log(ratio)-1.96*se),hi=Math.exp(Math.log(ratio)+1.96*se);
 let html=finding((delta>=0?'+':'')+dec.format(delta)+'%','2025 versus 2024','Check the population','The latest fatality change',`<p>Motorcycle rider and passenger deaths changed from <strong>${n(a.fatal)}</strong> in 2024 to <strong>${n(b.fatal)}</strong> in 2025. Riders alone: ${n(a.rider_fatal)} to ${n(b.rider_fatal)} (${dec.format(100*(b.rider_fatal/a.rider_fatal-1))}% change).</p><p>The submission refers to a 14% rise in rider fatalities. The appropriate comparison must use the same road-user population and year. Approximate 95% count-ratio interval for riders and passengers combined: <strong>${lo.toFixed(2)}–${hi.toFixed(2)}</strong> (1.0 means no change). This is a count comparison, not an exposure-adjusted risk estimate.</p>`);
 const h24=data.history.find(x=>x.year===2024),h25=data.history.find(x=>x.year===2025);
 html+=finding('+'+dec.format(100*(h25.fatal_rate/h24.fatal_rate-1))+'%','national fatality rate change','Mileage-adjusted context','The rise remains after accounting for national mileage',`<p>DfT RAS0102 reports ${dec.format(h24.fatal_rate)} motorcycle fatalities per billion motorcycle miles in 2024 and ${dec.format(h25.fatal_rate)} in 2025.</p><p>This national comparison accounts for total motorcycle mileage. It does not isolate changes in rider age, engine size, trip purpose or training. Use the Historical context view to explore the longer rate series.</p>`);
 html+=finding(pct(c.junction_collisions,c.recent_motorcycle_collisions),'of motorcycle-involved collisions','Descriptive support','How much occurs at or near junctions?',`<p>${n(c.junction_collisions)} of ${n(c.recent_motorcycle_collisions)} distinct motorcycle-involved collisions in 2021–2025 were at or near a junction. Junction status is unknown for ${n(c.junction_unknown_collisions)} (${pct(c.junction_unknown_collisions,c.recent_motorcycle_collisions)}).</p><p>This tests the proposed concentration at junctions. It does not establish that another road user failed to see the motorcycle.</p>`);
 html+=finding(pct(c.rural_bend_fatal,c.recent_fatal),'recorded rural-bend fatalities','Incomplete measurement','The rural-bend claim needs a tighter definition',`<p>${n(c.rural_bend_fatal)} of ${n(c.recent_fatal)} motorcycle fatalities have both rural location and a recorded bend manoeuvre. Bend status is unavailable for ${n(c.fatal_bend_unknown)} fatal casualties (${pct(c.fatal_bend_unknown,c.recent_fatal)}).</p><p>This is a recorded subset, not a complete measure of deaths on rural bends. Manoeuvre coding changes and the difference between road geometry and vehicle manoeuvre prevent a clean test of the submission’s approximately 50% claim.</p><details><summary>Check bend coverage by year</summary>${table(['Year','Fatal casualties','Recorded rural bend','Bend unavailable'],c.bend_by_year.map(r=>[r.year,n(r.fatal),n(r.rural_bend_fatal),n(r.fatal_unknown_bend)]))}</details>`);
 html+=finding(pct(c.class_125_collisions,c.recent_motorcycle_collisions),'involve the 125cc category','Partial test only','Small motorcycles are not a learner-rider identifier',`<p>${n(c.class_125_collisions)} of ${n(c.recent_motorcycle_collisions)} motorcycle-involved collisions include the 125cc category. Including the separate 50cc-and-under category gives ${pct(c.up_to_125_collisions,c.recent_motorcycle_collisions)}. Collisions are counted once within each definition.</p><p>This cannot verify a claim about A1 licence holders, learners or fleet-adjusted risk. Licence status and a matching fleet denominator are absent. Multiple motorcycle categories may occur in the same collision.</p>`);
 html+=finding('Not measured','in these open-data files','Additional evidence needed','Braking failure, ABS and training effectiveness',`<p>Skidding status is unknown for ${pct(c.skid_unknown_casualties,c.recent_casualties)} of recent motorcycle casualties. Even known skidding does not identify wheel lock, braking technique, reaction delay or whether ABS was fitted and active.</p><p>The data can identify groups and circumstances for investigation. It cannot establish that a particular training method caused fatalities or that a technology would have prevented them.</p>`);
 $('findings-content').innerHTML=html;
 const rr=data.explorer.rows.filter(r=>r[cols.year]===2024||r[cols.year]===2025);
 const old=group(rr.filter(r=>r[cols.year]===2024),'age','fatal'),newer=group(rr.filter(r=>r[cols.year]===2025),'age','fatal');
 $('change-table').innerHTML=table(['Casualty age','2024 fatal','2025 fatal','Change','Count change','Interpretation'],labels.age.map((name,i)=>{let x=old.get(i)||0,y=newer.get(i)||0,d=y-x;return[name,n(x),n(y),(d>0?'+':'')+n(d),x?(d>0?'+':'')+dec.format(100*d/x)+'%':'Not defined',Math.min(x,y)<20?'Small counts':'Descriptive comparison'];}));
}
function renderHistory(){let start=+$('history-from').value,metric=$('history-metric').value,rows=data.history.filter(r=>r.year>=start);chart('history-chart',rows.map(r=>({year:r.year,value:r[metric]})),(metric==='fatal'?'Annual motorcycle fatal casualties':'Fatalities per billion motorcycle miles')+', '+start+'–2025. Exact figures are in the historical table.',true);$('history-table').innerHTML=table(['Year','Fatal','Fatal per billion miles','Recorded serious','Slight','All motorcycle casualties'],rows.map(r=>[r.year,n(r.fatal),dec.format(r.fatal_rate),n(r.serious),n(r.slight),n(r.total)]));}
function renderAudit(){const a=data.audit;const entries=[['Source collision rows',n(a.source_rows.collision)],['Source vehicle rows',n(a.source_rows.vehicle)],['Source casualty rows',n(a.source_rows.casualty)],['Detailed motorcycle casualties',n(a.detail_motorcycle_casualties)],['Duplicate casualty / vehicle / collision keys',`${a.checks.motorcycle_casualty_duplicate_keys} / ${a.checks.motorcycle_vehicle_duplicate_keys} / ${a.checks.selected_collision_duplicate_keys}`],['Unmatched casualty-to-vehicle joins',n(a.checks.casualties_without_motorcycle_vehicle)],['Unmatched casualty-to-collision joins',n(a.checks.casualties_without_collision)],['Invalid nonfatal severity weights',n(a.checks.nonfatal_invalid_adjustment)],['Casualty and vehicle type disagreements',n(a.checks.casualty_vehicle_type_disagreements)],['Annual and aggregate totals','Reconciled']];$('audit').innerHTML=entries.map(([k,v])=>`<div class="audit-row"><span>${esc(k)}</span><strong>${esc(v)}</strong></div>`).join('');}
function download(){const line=items=>items.map(v=>'"'+String(v).replaceAll('"','""')+'"').join(',');const rows=[['Motorcycle Evidence — Dr Owen Williams'],['Source','DfT STATS19; retrieved 2026-10-14'],['Selection',$('scope').textContent],['Note','Counts of casualties, not risk rates. Adjusted KSI is an estimate.'],['Year','All casualties','Fatal casualties','Recorded KSI','Adjusted KSI'],...summary.map(r=>[r.year,r.total,r.fatal,r.rawksi,r.adjksi.toFixed(2)])];const blob=new Blob(['\ufeff'+rows.map(line).join('\r\n')],{type:'text/csv;charset=utf-8'}),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download=`motorcycle-summary-${$('from').value}-${$('to').value}.csv`;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);}
async function init(){try{const names=['explorer','labels','annual','history','claims','audit'];const loaded=await Promise.all(names.map(async name=>{const r=await fetch(`data/${name}.json`);if(!r.ok)throw Error(`${name}: ${r.status}`);return r.json();}));data=Object.fromEntries(names.map((k,i)=>[k,loaded[i]]));labels=data.labels;cols=Object.fromEntries(data.explorer.columns.map((x,i)=>[x,i]));const years=data.annual.map(x=>[x.year,x.year]);options('from',years,false);options('to',years,false);for(const k of ['age','bike','area','role'])options(k,labels[k].map((x,i)=>[i,x]));options('history-from',data.history.map(x=>[x.year,x.year]),false);$('from').value='2021';$('to').value='2025';$('history-from').value=String(data.history[0].year);$('filters').addEventListener('change',render);$('filters').addEventListener('submit',e=>e.preventDefault());$('metric').addEventListener('change',render);$('reset').addEventListener('click',()=>{$('from').value='2021';$('to').value='2025';for(const k of ['age','bike','area','role'])$(k).value='all';$('metric').value='fatal';render();});$('download').addEventListener('click',download);$('history-from').addEventListener('change',renderHistory);$('history-metric').addEventListener('change',renderHistory);$('history-full').addEventListener('click',()=>{$('history-from').value=String(data.history[0].year);renderHistory();});$('history-modern').addEventListener('click',()=>{$('history-from').value='2005';renderHistory();});render();renderFindings();renderHistory();renderAudit();$('loading').hidden=true;window.analysisReady=true;}catch(e){$('loading').hidden=true;$('error').hidden=false;$('error').textContent='The analysis could not be loaded. Please reload the page. If this continues, the data files may be unavailable.';console.error(e);}}
init();
